import{_ as l,o as n,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Scrubs Scheduling in Reef and Beyond - Ronen Friedman, IBM","description":"","frontmatter":{"title":"Scrubs Scheduling in Reef and Beyond - Ronen Friedman, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Scrub 代码","Ceph 存储系统","性能优化","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Scrubs_Scheduling_in_Reef_and_Beyond_-_Ronen_Friedman_IBM.md","filePath":"posts/2023/Scrubs_Scheduling_in_Reef_and_Beyond_-_Ronen_Friedman_IBM.md","lastUpdated":1780459816000}'),s={name:"posts/2023/Scrubs_Scheduling_in_Reef_and_Beyond_-_Ronen_Friedman_IBM.md"};function a(o,e,t,u,c,d){return n(),i("div",null,[...e[0]||(e[0]=[r('<p>会议纪要</p><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li><strong>主讲人</strong>: London Friedman</li><li><strong>时间</strong>: 会议持续约40分钟</li><li><strong>主题</strong>: Ceph 存储系统中的 scrub 代码维护和改进</li></ul><h4 id="会议内容总结" tabindex="-1">会议内容总结 <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结&quot;">​</a></h4><ol><li><p><strong>Scrub 代码维护</strong>:</p><ul><li>London Friedman 过去三年持续维护 Ceph 中的 scrub 代码，并得到 Sam 及其他贡献者的协助。</li><li>在这段时间内，对 scrubbing 过程进行了多项改进。</li></ul></li><li><p><strong>改进成果</strong>:</p><ul><li>改进了 scrub 状态的更新机制，确保每几秒钟发送一次更新，便于通过 PG dump 或 query 命令获取最新的 scrub 信息。</li><li>优化了 scrub 的 chunk size，以提升 deep scrub 和 shallow scrub 的性能。</li><li>引入了 M clock 调度器，减少对客户端 IO 的影响，增强集群管理的灵活性。</li></ul></li><li><p><strong>重要变更</strong>:</p><ul><li><strong>Chunk Size</strong>: 调整了 scrub 的 chunk size，优化不同 scrub 类型的性能。</li><li><strong>M clock Scheduler</strong>: 新的调度器在执行 scrub 时对客户端 IO 的影响更小，增加了集群管理的灵活性。</li></ul></li><li><p><strong>未来计划</strong>:</p><ul><li>继续增强对系统中超时和慢响应部分的自检、警告和修复功能。</li><li>设计新的 scrub 调度器，解决现有系统中的代码维护复杂性和调度效率问题。</li></ul></li><li><p><strong>新调度器设计</strong>:</p><ul><li>引入新的 scrub 目标（Target）概念，每个 PG 维护 shallow 和 deep scrub 的独立目标。</li><li>使用 urgency 参数来决定 scrub 的优先级，取代旧的基于 flags 的系统。</li><li>引入“not before”机制，避免对暂时无法 scrub 的 PG 进行重复检查。</li></ul></li><li><p><strong>性能和维护</strong>:</p><ul><li>讨论了 scrub 代码的性能优化和维护问题，强调了代码的清晰性和可维护性的重要性。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续开发和测试新的 scrub 调度器。</li><li>监控和调整 scrub 相关的配置参数，尤其是 chunk size 和调度器相关参数。</li><li>收集用户反馈，进一步优化 scrub 过程的性能和可靠性。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>本次会议详细讨论了 Ceph 存储系统中 scrub 代码的维护和改进工作，展示了过去几年的成果，并提出了未来的改进方向和计划。通过引入新的调度器和优化参数设置，目标是提高 scrub 过程的效率和系统的整体性能。</p>',9)])])}const b=l(s,[["render",a]]);export{p as __pageData,b as default};
